function getPartFromImage(dataUri) {
  const [header, data] = dataUri.split(',');
  const mimeType = header.match(/:(.*?);/)?.[1] || 'image/jpeg';
  return {
    inlineData: {
      mimeType,
      data
    }
  };
}

function isFirebaseKey(key) {
    return key === firebaseConfig.apiKey || key.startsWith("AIzaSyDrFjYv2c322zzCMsgpVttjUz9lWDrBoUg");
}

async function getCombinedReading(
  birthDetails,
  options,
  advancedOptions,
  lifeEvents,
  outputLanguage,
  exSpouseDetails,
  enableGoogleSearch = false,
  visuals,
  apiKey,
  model = 'gemini-3-flash-preview'
) {
  if (!apiKey || !apiKey.trim()) throw new Error("API Key is missing. Please add it in Settings.");
  if (isFirebaseKey(apiKey.trim())) {
      throw new Error("Invalid API Key. You are using the Firebase Database key. Please use a valid Gemini API Key from Google AI Studio.");
  }

  const ai = new GoogleGenAI({ apiKey: apiKey.trim() });
  const textPrompt = buildAstrologyPrompt(birthDetails, options, advancedOptions, lifeEvents, outputLanguage, exSpouseDetails, visuals, false);

  const parts = [{ text: textPrompt }];
  if (visuals?.face) parts.push(getPartFromImage(visuals.face));
  if (visuals?.palm) parts.push(getPartFromImage(visuals.palm)); 

  try {
    const config = { temperature: 0.7 };
    if (enableGoogleSearch) {
      config.tools = [{ googleSearch: {} }];
    }

    const response = await ai.models.generateContent({
      model: model,
      contents: { parts },
      config: config,
    });
    return { 
      reading: response.text || "Cosmic signal lost.", 
      groundingSources: response.candidates?.[0]?.groundingMetadata?.groundingChunks || [] 
    };
  } catch (error) {
    console.error("Gemini API Error:", error);

    const errString = error.toString();
    const message = error.message || errString;

    if (message.includes("403") || message.includes("PERMISSION_DENIED")) {
        if (message.includes("API_KEY_SERVICE_BLOCKED") || message.includes("consumer")) {
             throw new Error("Service Blocked: The API Key provided is not enabled for Gemini. \n\nIMPORTANT: Do not use the Firebase Key found in the code. Create a new key at aistudio.google.com.");
        }
        throw new Error("Access Denied (403). Your API Key is invalid or expired. Please update it in Settings.");
    }
    throw error;
  }
}

async function initializeChatSession(
  birthDetails,
  options,
  advancedOptions,
  lifeEvents,
  outputLanguage,
  history = [],
  exSpouseDetails,
  enableGoogleSearch = false,
  visuals,
