  if (isFirebaseKey(apiKey.trim())) {
      throw new Error("Invalid API Key. You are using the Firebase Database key. Please use a valid Gemini API Key.");
  }

  const ai = new GoogleGenAI({ apiKey: apiKey.trim() });
  const systemInstruction = buildAstrologyPrompt(birthDetails, options, advancedOptions, lifeEvents, outputLanguage, exSpouseDetails, visuals, true);

  const geminiHistory = history.map(msg => ({
    role: msg.role === 'user' ? 'user' : 'model',
    parts: [{ text: msg.text }]
  }));

  const config = {
    systemInstruction,
    temperature: 0.8,
  };

  if (enableGoogleSearch) {
    config.tools = [{ googleSearch: {} }];
  }

  return ai.chats.create({
    model: model,
    history: geminiHistory,
    config: config,
  });
}

async function* sendChatMessage(chatSession, message) {
  const responseStream = await chatSession.sendMessageStream({ message });
  for await (const chunk of responseStream) {
    if (chunk.text) yield chunk.text;
  }
}

