// Check if the provided key matches the public Firebase key
function isFirebaseKey(key) {
    if (!key) return false;
    const cleanKey = key.trim();
    // Check against the known Firebase config key or general Firebase key patterns
    return cleanKey === firebaseConfig.apiKey || 
           (cleanKey.startsWith("AIza") && cleanKey.includes("DrFjYv2")); // Signature of your firebase key
}

const getOrGenerateUserId = () => {
  let userId = localStorage.getItem('cosmic_user_id');
  if (!userId) {
    userId = 'user_' + Math.random().toString(36).substring(2, 11) + Date.now().toString(36);
    localStorage.setItem('cosmic_user_id', userId);
  }
  return userId;
};

const syncToFirebase = async (userId, data) => {
  try {
    const userRef = ref(db, `users/${userId}`);
    await set(userRef, {
      ...data,
      lastUpdated: new Date().toISOString()
    });
    return true;
  } catch (error) {
    console.error("Firebase Sync Error:", error);
    return false;
  }
};

const loadFromFirebase = async (userId) => {
  try {
    const userRef = ref(db, `users/${userId}`);
    const snapshot = await get(userRef);
    if (snapshot.exists()) {
      return snapshot.val();
    }
    return null;
  } catch (error) {
    console.error("Firebase Load Error:", error);
    return null;
  }
};

