// -----------------------------------------------------------------------------
// ERROR BOUNDARY
// -----------------------------------------------------------------------------

class ErrorBoundary extends React.Component {
  constructor(props) {
    super(props);
    this.state = { hasError: false, error: null, errorInfo: null };
  }

  static getDerivedStateFromError(error) {
    return { hasError: true, error };
  }

  componentDidCatch(error, errorInfo) {
    console.error("React Error Boundary caught an error:", error, errorInfo);
    this.setState({ errorInfo });
  }

  handleReset = () => {
      localStorage.removeItem('cosmic_compass_master_v3');
      window.location.reload();
  }

  render() {
    if (this.state.hasError) {
      return (
        <div className="flex flex-col items-center justify-center min-h-screen text-center p-8 text-white">
          <div className="bg-red-900/20 border border-red-500/50 p-8 rounded-3xl max-w-2xl backdrop-blur-xl shadow-2xl">
              <div className="flex justify-center mb-6">
                <AlertTriangle size={64} className="text-red-500" />
              </div>
              <h2 className="text-3xl font-serif mb-4 text-red-400">Cosmic Alignment Error</h2>
              <p className="mb-6 text-gray-300">The stars have encountered a misalignment in the application logic.</p>

              <div className="bg-black/50 p-4 rounded-xl text-left text-xs text-red-300 overflow-auto mb-8 max-h-40 font-mono border border-red-900/50">
                  <p className="font-bold mb-2">{this.state.error && this.state.error.toString()}</p>
                  <p className="opacity-70 whitespace-pre-wrap">{this.state.errorInfo && this.state.errorInfo.componentStack}</p>
              </div>

              <div className="flex gap-4 justify-center flex-wrap">
                  <button onClick={() => window.location.reload()} className="px-6 py-3 bg-indigo-600 rounded-xl hover:bg-indigo-500 transition-all font-bold shadow-lg shadow-indigo-500/20">
                    Reload Portal
                  </button>
                  <button onClick={this.handleReset} className="px-6 py-3 bg-red-600/10 border border-red-500/50 rounded-xl hover:bg-red-600/20 text-red-300 transition-all font-bold">
                    Reset Cosmic Data
                  </button>
              </div>
          </div>
        </div>
      );
    }

    return this.props.children;
  }
}

