    let session = currentChatSession;
    if (!session) {
      setChatLoading(true);
      try {
        session = await initializeChatSession(
            birthDetails, 
            readingOptions, 
            advancedReadingOptions, 
            lifeEvents, 
            outputLanguage, 
            chatHistory, 
            exSpouseDetails, 
            enableGoogleSearch, 
            visuals,
            process.env.API_KEY || '',
            selectedModel
