      model: model,
      contents: { parts },
      config: config,
    });
    return { 
      reading: response.text || "Cosmic signal lost.", 
      groundingSources: response.candidates?.[0]?.groundingMetadata?.groundingChunks || [] 
    };
  } catch (error) {
    console.error("Gemini API Error:", error);

    const errString = error.toString();
    const message = error.message || errString;

    if (message.includes("403") || message.includes("PERMISSION_DENIED")) {
        throw new Error("Access Denied (403). Your API Key is invalid or expired.");
    }
    throw error;
  }
}

async function initializeChatSession(
  birthDetails,
  options,
  advancedOptions,
  lifeEvents,
  outputLanguage,
  history = [],
  exSpouseDetails,
  enableGoogleSearch = false,
  visuals,
  apiKey,
  model = 'gemini-3-flash-preview'
) {
  if (!apiKey || !apiKey.trim()) throw new Error("API Key is missing. Please add it in Settings.");
  if (isFirebaseKey(apiKey)) throw new Error("INVALID_KEY:FIREBASE");

  const ai = new GoogleGenAI({ apiKey: apiKey.trim() });
  const systemInstruction = buildAstrologyPrompt(birthDetails, options, advancedOptions, lifeEvents, outputLanguage, exSpouseDetails, visuals, true);

  const geminiHistory = history.map(msg => ({
    role: msg.role === 'user' ? 'user' : 'model',
    parts: [{ text: msg.text }]
  }));

  const config = {
    systemInstruction,
    temperature: 0.8,
  };

  if (enableGoogleSearch) {
    config.tools = [{ googleSearch: {} }];
  }

  return ai.chats.create({
    model: model,
    history: geminiHistory,
    config: config,
  });
}

async function* sendChatMessage(chatSession, message) {
  const responseStream = await chatSession.sendMessageStream({ message });
  for await (const chunk of responseStream) {
    if (chunk.text) yield chunk.text;
  }
}

