    // Recovery effect from cloud
    useEffect(() => {
        const recoverData = async () => {
        try {
            const remoteData = await loadFromFirebase(userId);
            if (remoteData) {
            // STRICT RECOVERY FOR DEFAULT PROFILE:
            // If the profile name matches the default (Harshkumar), we ensure the timeline includes the detailed events.
            // If remote has fewer events than our new Master Timeline (23 events), we prioritize the Master Timeline.
            const isDefaultUser = remoteData.birthDetails?.name?.toLowerCase().includes('harshkumar');
            const remoteEventCount = remoteData.lifeEvents?.length || 0;
            const defaultEventCount = DEFAULT_STATE.lifeEvents.length;

            let resolvedLifeEvents = remoteData.lifeEvents;

            // If it's the default user and they have fewer events than our new master list, 
            // upgrade them to the master list to recover missing events.
            if (isDefaultUser && remoteEventCount < defaultEventCount) {
                console.log("Restoring Master Timeline for main profile...");
                resolvedLifeEvents = DEFAULT_STATE.lifeEvents;
            } else if (!remoteData.lifeEvents || remoteData.lifeEvents.length === 0) {
                resolvedLifeEvents = DEFAULT_STATE.lifeEvents;
            }

            setAppState(prev => ({
                ...prev,
                ...remoteData,
                lifeEvents: resolvedLifeEvents,
                chatHistory: remoteData.chatHistory || prev.chatHistory,
                visuals: remoteData.visuals || prev.visuals
            }));
            setIsFirebaseSynced(true);
            }
        } catch (e) {
            console.error("Cloud Access Failure:", e);
        } finally {
            setIsRecovering(false);
            setCloudLockReleased(true);
        }
        };
        recoverData();
    }, [userId]);

    const triggerSync = useCallback(async (data) => {
        if (!cloudLockReleased) return false;
        setIsSyncing(true);
        const success = await syncToFirebase(userId, data);
        setIsFirebaseSynced(success);
        setIsSyncing(false);
        return success;
    }, [userId, cloudLockReleased]);

    // Regular auto-sync debounce (2s)
    useEffect(() => {
        saveStateToLocalStorage(MASTER_STORAGE_KEY, appState);
        if (cloudLockReleased) {
            const timer = setTimeout(() => triggerSync(appState), 2000);
            return () => clearTimeout(timer);
        }
