        const newEvents = lifeEvents.filter((_, i) => i !== index);
        updateAppState({ lifeEvents: newEvents });
    };

    const handleUpdateEvent = (index, field, value) => {
        const newEvents = [...lifeEvents];
        newEvents[index] = { ...newEvents[index], [field]: value };
