            let errorMessage = err.message || "Failed to generate reading.";
            if (errorMessage.includes("403") || errorMessage.includes("Service Blocked") || errorMessage.includes("INVALID_KEY")) {
                setShowSettings(true);
            }
            setError(errorMessage);
        } finally {
        setLoading(false);
        }
    };

    const handleFileUpload = (type) => (e) => {
        const file = e.target.files?.[0];
        if (file) {
        const reader = new FileReader();
        reader.onloadend = () => {
            const newVisuals = { ...visuals, [type]: reader.result };
            updateAppState({ visuals: newVisuals });
        };
        reader.readAsDataURL(file);
        }
    };

    if (initError) {
        return (
