                        {/* Standard Lo Shu Layout: 4 9 2 / 3 5 7 / 8 1 6 */}
                        {[4, 9, 2, 3, 5, 7, 8, 1, 6].map((num) => {
                        const count = numerologyData.loshuCounts[num] || 0;
                        const hasNum = count > 0;
                        // Determine background based on element
                        // 9=Fire(Red), 1=Water(Blue), 3,4=Wood(Green), 6,7=Metal(Gold/Grey), 2,5,8=Earth(Yellow/Brown)
                        let bgClass = "bg-white/5 text-gray-700";
                        if (hasNum) {
                            if ([9].includes(num)) bgClass = "bg-red-500/20 text-red-200 border-red-500/50 shadow-[0_0_10px_rgba(239,68,68,0.3)]";
