const saveStateToLocalStorage = (key, state) => {
  try {
    const serializedState = JSON.stringify(state);
    localStorage.setItem(key, serializedState);
    return true;
  } catch (error) {
    if (error.name === 'QuotaExceededError' || error.name === 'NS_ERROR_DOM_QUOTA_REACHED') {
      console.warn("LocalStorage quota exceeded. Attempting to save without large visual data...");
      if (typeof state === 'object' && state !== null && 'visuals' in state) {
        try {
          const fallbackState = { ...state, visuals: {} };
          localStorage.setItem(key, JSON.stringify(fallbackState));
          return true;
        } catch (innerError) {
          console.error("Critical storage failure:", innerError);
        }
      }
    }
    return false;
  }
};

const loadStateFromLocalStorage = (key, defaultValue) => {
  try {
    const serializedState = localStorage.getItem(key);
    if (!serializedState) return defaultValue;
    return JSON.parse(serializedState);
  } catch (error) {
    return defaultValue;
  }
};

// Numerology Calculation Engine
const calculateNumerology = (dob) => {
    if (!dob) return { driver: 0, conductor: 0, loshu: {}, planes: [] };

    // YYYY-MM-DD
    const dateParts = dob.split('-');
    if (dateParts.length !== 3) return { driver: 0, conductor: 0, loshu: {}, planes: [] };

    const year = dateParts[0];
    const month = dateParts[1];
    const day = dateParts[2];

    const sumDigits = (n) => {
        let sum = 0;
        let num = n;
        while (num > 0 || sum > 9) {
            if (num === 0) {
                num = sum;
                sum = 0;
            }
            sum += num % 10;
            num = Math.floor(num / 10);
        }
        return sum;
    };

    // Lo Shu Count (Frequency of digits in full date)
    const allDigits = (day + month + year).split('').map(Number).filter(n => n > 0); 
    const loshuCounts = {};
    allDigits.forEach(d => loshuCounts[d] = (loshuCounts[d] || 0) + 1);

    // Driver: Sum of day only
    const dayNum = parseInt(day);
    const driver = sumDigits(dayNum);

    // Conductor: Sum of full date
    const fullDateStr = year + month + day;
    let fullSum = 0;
    for(let char of fullDateStr) fullSum += parseInt(char);
    const conductor = sumDigits(fullSum);

    // Planes Calculation
    const planes = [];
    if(loshuCounts[4] && loshuCounts[9] && loshuCounts[2]) planes.push("Mental Plane (4-9-2)");
    if(loshuCounts[3] && loshuCounts[5] && loshuCounts[7]) planes.push("Emotional Plane (3-5-7)");
    if(loshuCounts[8] && loshuCounts[1] && loshuCounts[6]) planes.push("Practical Plane (8-1-6)");
    if(loshuCounts[4] && loshuCounts[3] && loshuCounts[8]) planes.push("Thought Plane (4-3-8)");
    if(loshuCounts[9] && loshuCounts[5] && loshuCounts[1]) planes.push("Willpower Plane (9-5-1)");
    if(loshuCounts[2] && loshuCounts[7] && loshuCounts[6]) planes.push("Action Plane (2-7-6)");
    if(loshuCounts[4] && loshuCounts[5] && loshuCounts[6]) planes.push("Golden Raj Yoga (4-5-6)");
    if(loshuCounts[2] && loshuCounts[5] && loshuCounts[8]) planes.push("Silver Raj Yoga (2-5-8)");

    return { driver, conductor, loshuCounts, planes };
};

