import React, { useState, useEffect, useRef } from 'react';
import { ChatMessage } from '../types';
import { History as HistoryIcon, Send, Sparkles, ArrowLeft, Trash2, CheckCircle, Cloud } from 'lucide-react';

interface ChatInterfaceProps {
  chatHistory: ChatMessage[];
  onSendMessage: (message: string) => void;
  loading: boolean;
  error: string | null;
  onBackToForm: () => void;
  onClearChat: () => void;
  suggestedQuestions: string[];
  isSyncing?: boolean;
  isFirebaseSynced?: boolean;
}

const ChatInterface: React.FC<ChatInterfaceProps> = ({
  chatHistory,
  onSendMessage,
  loading,
  error,
  onBackToForm,
  onClearChat,
  suggestedQuestions,
  isSyncing,
  isFirebaseSynced,
}) => {
  const [currentInput, setCurrentInput] = useState<string>('');
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(scrollToBottom, [chatHistory]);

  const handleSend = () => {
    if (currentInput.trim()) {
      onSendMessage(currentInput);
      setCurrentInput('');
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  return (
    <div className="flex flex-col h-[75vh] md:h-[80vh] glass rounded-3xl overflow-hidden shadow-2xl border border-white/10 animate-in fade-in zoom-in-95 duration-300">
      {/* Header */}
      <div className="px-6 py-4 bg-white/5 border-b border-white/10 flex justify-between items-center">
        <div className="flex items-center space-x-3">
          <div className="w-10 h-10 rounded-full bg-gradient-to-tr from-purple-500 to-indigo-500 flex items-center justify-center shadow-lg">
            <Sparkles className="text-white" size={20} />
          </div>
          <div>
            <h2 className="text-lg font-bold text-white leading-tight">Universal Oracle</h2>
            <div className="flex items-center text-[10px] font-black uppercase tracking-tighter">
              {isSyncing ? (
                <span className="text-blue-400 animate-pulse flex items-center">
                  <Cloud size={10} className="mr-1" />
                  Archiving...
                </span>
              ) : isFirebaseSynced ? (
                <div className="flex items-center text-green-400">
                  <CheckCircle size={10} className="mr-1" />
                  Akashic Record Synced
                </div>
              ) : (
                <div className="flex items-center text-gray-500">
                  <HistoryIcon size={10} className="mr-1" />
                  Session Persistent
                </div>
              )}
            </div>
          </div>
        </div>
        <div className="flex items-center space-x-2">
          <button
            onClick={onClearChat}
            title="Clear Chat History"
            className="p-2 text-gray-400 hover:text-red-400 hover:bg-white/5 rounded-lg transition-all"
          >
            <Trash2 size={18} />
          </button>
          <button
            onClick={onBackToForm}
            className="flex items-center gap-2 px-4 py-1.5 text-xs font-bold bg-indigo-600/20 hover:bg-indigo-600/40 text-indigo-300 rounded-lg transition-all border border-indigo-500/20"
          >
            <ArrowLeft size={14} /> Chart
          </button>
        </div>
      </div>

      <div className="flex-1 flex overflow-hidden">
        <div className="flex-1 flex flex-col overflow-hidden">
          {chatHistory.length <= 1 && suggestedQuestions.length > 0 && (
            <div className="p-4 bg-white/5 border-b border-white/5 overflow-x-auto whitespace-nowrap scrollbar-hide">
              <p className="text-[10px] uppercase tracking-wider text-gray-400 mb-2 px-1">Inquiry Paths</p>
              <div className="flex space-x-2">
                {suggestedQuestions.map((q, i) => (
                  <button
                    key={i}
                    onClick={() => onSendMessage(q)}
                    className="px-4 py-2 text-xs bg-indigo-500/10 hover:bg-indigo-500/20 border border-indigo-500/20 rounded-full text-indigo-200 transition-all"
                  >
                    {q}
                  </button>
                ))}
              </div>
            </div>
          )}

          <div className="flex-1 overflow-y-auto p-6 space-y-6 custom-scrollbar bg-black/10">
            {chatHistory.length === 0 && !loading && (
              <div className="h-full flex flex-col items-center justify-center opacity-30 text-center space-y-4">
                <HistoryIcon size={48} className="text-indigo-400" />
                <p className="font-serif italic text-lg">Past sessions are preserved in your local Akashic field.</p>
              </div>
            )}
            {chatHistory.map((msg, index) => (
              <div
                key={index}
                className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'} animate-in fade-in slide-in-from-bottom-2 duration-300`}
              >
                <div
                  className={`max-w-[85%] px-5 py-4 rounded-2xl shadow-lg border ${
                    msg.role === 'user'
                      ? 'bg-indigo-600/30 border-indigo-500/40 text-indigo-50'
                      : 'bg-white/5 border-white/10 text-gray-200'
                  }`}
                >
                  <p className="text-sm leading-relaxed whitespace-pre-wrap font-medium">{msg.text || (loading && index === chatHistory.length - 1 ? '...' : '')}</p>
                </div>
              </div>
            ))}
            {loading && chatHistory.length > 0 && chatHistory[chatHistory.length - 1].text === '' && (
              <div className="flex justify-start">
                <div className="bg-white/5 border border-white/10 px-5 py-3 rounded-2xl flex items-center space-x-3">
                  <div className="flex space-x-1">
                    <div className="w-1.5 h-1.5 bg-indigo-400 rounded-full animate-bounce"></div>
                    <div className="w-1.5 h-1.5 bg-indigo-400 rounded-full animate-bounce [animation-delay:0.2s]"></div>
                    <div className="w-1.5 h-1.5 bg-indigo-400 rounded-full animate-bounce [animation-delay:0.4s]"></div>
