  }, [appState, triggerSync, cloudLockReleased]);

  const saveSettings = () => {
    localStorage.setItem('cosmic_selected_model', selectedModel);
    setShowSettings(false);
    setCurrentChatSession(undefined); // Reset chat
  };

  const handleSendMessage = async (message: string) => {
    let session = currentChatSession;
    if (!session) {
      setChatLoading(true);
      try {
        session = await initializeChatSession(
            birthDetails, 
            readingOptions, 
            advancedReadingOptions, 
            lifeEvents, 
            outputLanguage, 
            chatHistory, 
            exSpouseDetails, 
            enableGoogleSearch, 
            visuals,
            process.env.API_KEY || '',
            selectedModel
        );
        setCurrentChatSession(session);
      } catch (err: any) { 
        setChatError(err.message); 
        setChatLoading(false); 
        return; 
      }
    }

    const newUserMsg: ChatMessage = { role: 'user', text: message };
    setChatLoading(true);

    // Set initial response state
    setAppState(prev => ({
      ...prev,
      chatHistory: [...prev.chatHistory, newUserMsg, { role: 'model' as const, text: '' }]
    }));

    let fullText = '';
    try {
      const stream = sendChatMessage(session, message);
      for await (const chunk of stream) {
        fullText += chunk;
        setAppState(prev => {
          const hist = [...prev.chatHistory];
          if (hist.length > 0) {
            const last = hist[hist.length - 1];
            if (last.role === 'model') last.text = fullText;
          }
          const next = { ...prev, chatHistory: hist };
          // Immediate incremental save to ensure data isn't lost mid-stream
          saveStateToLocalStorage(CHAT_HISTORY_KEY, next.chatHistory);
          return next;
        });
      }

      // Final persistent save and cloud sync trigger
      setAppState(prev => {
        triggerSync(prev);
        return prev;
      });

    } catch (err: any) { 
      setChatError(err.message); 
    } finally { 
      setChatLoading(false); 
    }
  };

  const updateAppState = useCallback((updates: Partial<AppState>) => {
    setAppState((prev) => ({ ...prev, ...updates }));
    setIsFirebaseSynced(false);
  }, []);

  const handleAddEvent = () => {
    const newEvents = [...lifeEvents, { description: '', date: new Date().toISOString().split('T')[0], planet: 'Mars' }];
    updateAppState({ lifeEvents: newEvents });
