    const archivedChat = loadStateFromLocalStorage<ChatMessage[]>(CHAT_HISTORY_KEY, []);
    if (archivedChat.length > 0) {
        // Prefer archived chat if it has more messages or if main state has none
        if (archivedChat.length >= mainState.chatHistory.length) {
            mainState.chatHistory = archivedChat;
