/**
 * Robust singleton initialization for Firebase.
 * Wrapped in try-catch to ensure the app doesn't white-screen if Firebase fails to load.
 */
let app: FirebaseApp | undefined;
let dbInstance: Database | undefined;

try {
  // Check if app is already initialized to avoid "duplicate app" error
  app = getApps().length === 0 ? initializeApp(firebaseConfig) : getApp();

  // Initialize Database with explicit URL
  // This is critical for some regions or CDN builds to link correctly
  dbInstance = getDatabase(app, firebaseConfig.databaseURL);

  console.log("Firebase initialized successfully");
} catch (error) {
  console.error("FIREBASE INIT ERROR: Service database is not available or connection failed.", error);
  // We swallow the error so the rest of the app (Gemini AI, UI) still works in "Offline Mode"
}

// Export db, which might be undefined if init failed
export const db = dbInstance;

/**
 * Gets or creates a persistent unique ID for this device/browser.
 */
export const getOrGenerateUserId = (): string => {
  let userId = localStorage.getItem('cosmic_user_id');
  if (!userId) {
    userId = 'user_' + Math.random().toString(36).substring(2, 11) + Date.now().toString(36);
    localStorage.setItem('cosmic_user_id', userId);
  }
  return userId;
};

